old='''            var rawPoints = await (from p in historyQuery\n                                   join e in db.Employees.AsNoTracking() on p.EmployeeId equals e.EmployeeID\n                                   orderby p.CapturedAtUtc ascending\n                                   select new PointRow\n                                   {\n                                       EmployeeId = p.EmployeeId, EmployeeName = e.Name, SessionId = p.SessionId,\n                                       Latitude = p.Latitude, Longitude = p.Longitude, AccuracyMeters = p.AccuracyMeters,\n                                       DistanceMeters = p.DistanceFromOfficeMeters, RadiusMeters = p.AllowedRadiusMeters,\n                                       WithinRadius = p.IsWithinAllowedRadius, CapturedAtUtc = p.CapturedAtUtc,\n                                       CaptureSource = p.CaptureSource, SyncBatchId = p.SyncBatchId, SyncedAtUtc = p.SyncedAtUtc,\n                                       RecordedAtUtc = p.RecordedAtUtc\n                                   }).Take(2000).ToListAsync();\n\n            points = BuildPointRows(rawPoints);'''
new='''            var rawPoints = await historyQuery\n                .OrderBy(p => p.CapturedAtUtc)\n                .Take(2000)\n                .Select(p => new PointRow\n                {\n                    EmployeeId = p.EmployeeId, EmployeeName = string.Empty, SessionId = p.SessionId,\n                    Latitude = p.Latitude, Longitude = p.Longitude, AccuracyMeters = p.AccuracyMeters,\n                    DistanceMeters = p.DistanceFromOfficeMeters, RadiusMeters = p.AllowedRadiusMeters,\n                    WithinRadius = p.IsWithinAllowedRadius, CapturedAtUtc = p.CapturedAtUtc,\n                    CaptureSource = p.CaptureSource, SyncBatchId = p.SyncBatchId, SyncedAtUtc = p.SyncedAtUtc,\n                    RecordedAtUtc = p.RecordedAtUtc\n                }).ToListAsync();\n\n            var employeeNames = employees.ToDictionary(x => x.EmployeeID, x => x.Name);\n            foreach (var point in rawPoints)\n                point.EmployeeName = employeeNames.GetValueOrDefault(point.EmployeeId, $"Employee #{point.EmployeeId}");\n\n            points = BuildPointRows(rawPoints);'''
