old='''            var rawSessions = await (from s in sessionQuery\n                                     join e in db.Employees.AsNoTracking() on s.EmployeeId equals e.EmployeeID\n                                     where s.StartedAtUtc < toUtc &&\n                                           (s.EndedAtUtc == null || s.EndedAtUtc >= fromUtc)\n                                     orderby s.StartedAtUtc descending\n                                     select new SessionRow\n                                     {\n                                         EmployeeId = s.EmployeeId, EmployeeName = e.Name, SessionId = s.SessionId,\n                                         StartedUtc = s.StartedAtUtc, LastUpdateUtc = s.LastUpdateAtUtc,\n                                         EndedUtc = s.EndedAtUtc, EndReason = s.EndReason,\n                                         TotalPoints = s.TotalPoints, TotalDistanceMeters = s.TotalDistanceMeters\n                                     }).Take(500).ToListAsync();\n\n            sessions = rawSessions;'''
new='''            var rawSessions = await sessionQuery\n                .Where(s => s.StartedAtUtc < toUtc &&\n                            (s.EndedAtUtc == null || s.EndedAtUtc >= fromUtc))\n                .OrderByDescending(s => s.StartedAtUtc)\n                .Take(500)\n                .Select(s => new SessionRow\n                {\n                    EmployeeId = s.EmployeeId, EmployeeName = string.Empty, SessionId = s.SessionId,\n                    StartedUtc = s.StartedAtUtc, LastUpdateUtc = s.LastUpdateAtUtc,\n                    EndedUtc = s.EndedAtUtc, EndReason = s.EndReason,\n                    TotalPoints = s.TotalPoints, TotalDistanceMeters = s.TotalDistanceMeters\n                }).ToListAsync();\n\n            foreach (var session in rawSessions)\n                session.EmployeeName = employeeNames.GetValueOrDefault(session.EmployeeId, $"Employee #{session.EmployeeId}");\n\n            sessions = rawSessions;'''
